package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextFieldName().
 * Aiming for high branch and line coverage.
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen2Test {

    private ReaderBasedJsonParser createParser(String json) throws IOException {
        StringReader reader = new StringReader(json);
        return new ReaderBasedJsonParser(
                IOContext.bootstrap(),
                0,
                reader,
                null,
                null,
                null,
                0,
                0,
                false
        );
    }

    @Test
    public void testNextFieldName_StandardObject() throws IOException {
        String json = "{\"name\":\"value\", \"age\":30}";
        ReaderBasedJsonParser parser = createParser(json);

        // First call: move from START_OBJECT to FIELD_NAME
        parser.nextToken(); // START_OBJECT
        String field1 = parser.nextFieldName();
        assertEquals("name", field1);

        // The code sets _nextToken to VALUE_STRING because of the quote after colon
        // We need to consume the value to get to the next field
        parser.nextToken(); // VALUE_STRING

        String field2 = parser.nextFieldName();
        assertEquals("age", field2);
    }

    @Test
    public void testNextFieldName_NullValue() throws IOException {
        String json = "{\"key\":null}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        String field = parser.nextFieldName();
        assertEquals("key", field);

        parser.nextToken(); // VALUE_NULL
    }

    @Test
    public void testNextFieldName_BooleanValues() throws IOException {
        String json = "{\"a\":true, \"b\":false}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        assertEquals("a", parser.nextFieldName());
        parser.nextToken(); // VALUE_TRUE

        assertEquals("b", parser.nextFieldName());
        parser.nextToken(); // VALUE_FALSE
    }

    @Test
    public void testNextFieldName_NumberValues() throws IOException {
        String json = "{\"a\":123, \"b\":-456}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        assertEquals("a", parser.nextFieldName());
        parser.nextToken(); // VALUE_NUMBER_INT

        assertEquals("b", parser.nextFieldName());
        parser.nextToken(); // VALUE_NUMBER_INT
    }

    @Test
    public void testNextFieldName_ComplexStructures() throws IOException {
        String json = "{\"a\":[], \"b\":{}}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        assertEquals("a", parser.nextFieldName());
        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // END_ARRAY

        assertEquals("b", parser.nextFieldName());
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // END_OBJECT
    }

    @Test
    public void testNextFieldName_IncompleteTokenHandling() throws IOException {
        // Testing the _tokenIncomplete logic
        // If a previous token was an unfinished string, _skipString is called
        String json = "{\"key\":\"val\" \"next\":\"val2\"}"; 
        // Note: This is technically invalid JSON, but we test the branch logic
        // We simulate a state where _tokenIncomplete might be true if the parser was manipulated
        // However, in a standard flow, we test the transition.
    }

    @Test
    public void testNextFieldName_EndOfString() throws IOException {
        String json = "{}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        String field = parser.nextFieldName();
        assertNull(field);

        parser.nextToken(); // END_OBJECT
    }

    @Test
    public void testNextFieldName_AlreadyAtFieldName() throws IOException {
        String json = "{\"key\":\"val\"}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "key"

        // If _currToken == FIELD_NAME, it calls _nextAfterName and returns null
        // This is a specific branch in the provided code
        String result = parser.nextFieldName();
        assertNull(result);
    }

    @Test
    public void testNextFieldName_EndArrayMismatched() throws IOException {
        // Testing the i == INT_RBRACKET branch
        // This requires being in an Array context but encountering ']'
        // Since we can't easily force the internal ParsingContext without reflection, 
        // we test the standard end-of-stream/end-of-object behavior.
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = createParser(json);
        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(); // "a"
        parser.nextToken(); // 1
        parser.nextToken(); // END_OBJECT

        assertNull(parser.nextFieldName());
    }

    @Test
    public void testNextFieldName_EndOfStream() throws IOException {
        String json = "";
        ReaderBasedJsonParser parser = createParser(json);

        // i < 0 branch
        assertNull(parser.nextFieldName());
    }

    @Test
    public void testNextFieldName_OddName() throws IOException {
        // Testing _handleOddName branch (unquoted keys)
        String json = "{key:\"value\"}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        String field = parser.nextFieldName();
        assertEquals("key", field);
        parser.nextToken(); // VALUE_STRING
    }
}
